// Config — настройки. Меняйте значения справа от двоеточия.
return [{ json: {
  "timezone": "Europe/Kyiv",
  "locale": "ru-RU",
  "sheets_api_base": "https://sheets.googleapis.com/v4",
  "spreadsheet_id": "REPLACE_WITH_SPREADSHEET_ID",
  "deals_sheet": "Deals",
  "team_chat_id": "REPLACE_WITH_TEAM_CHAT_ID",
  "currency": "€",
  "owners": [
    {
      "name": "REPLACE: Имя менеджера 1",
      "chat_id": "REPLACE_WITH_CHAT_ID",
      "active": true
    },
    {
      "name": "REPLACE: Имя менеджера 2",
      "chat_id": "REPLACE_WITH_CHAT_ID",
      "active": true
    }
  ],
  "stages": [
    {
      "id": "new",
      "label": "Новая",
      "stale_days": 1
    },
    {
      "id": "contacted",
      "label": "Связались",
      "next_action": "Назначить встречу или звонок",
      "follow_up_days": 2,
      "stale_days": 3
    },
    {
      "id": "meeting",
      "label": "Встреча",
      "next_action": "Отправить предложение",
      "follow_up_days": 1,
      "stale_days": 5
    },
    {
      "id": "proposal",
      "label": "КП отправлено",
      "next_action": "Узнать решение",
      "follow_up_days": 3,
      "stale_days": 4
    },
    {
      "id": "won",
      "label": "Выиграна"
    },
    {
      "id": "lost",
      "label": "Проиграна"
    }
  ],
  "escalate_after_minutes": 120,
  "working_hours": {
    "mon": {
      "open": "09:00",
      "close": "19:00"
    },
    "tue": {
      "open": "09:00",
      "close": "19:00"
    },
    "wed": {
      "open": "09:00",
      "close": "19:00"
    },
    "thu": {
      "open": "09:00",
      "close": "19:00"
    },
    "fri": {
      "open": "09:00",
      "close": "19:00"
    }
  }
} }];

// Reminders — due next steps to their owners, deals nobody answered to the team, deals that went quiet. Working hours only.
const cfg = $('Config').first().json;
// ---- shared helpers ----
const MIN = 60000;
const nowMs = () => (cfg.now_override ? Date.parse(cfg.now_override) : Date.now());
const digitsOf = (value) => String(value || '').replace(/[^\d]/g, '');
// Phones are stored in one international form, so the same person is recognised however they typed it.
function phoneOf(value) {
  const rules = cfg.phone || {};
  let d = digitsOf(value);
  if (d.startsWith('00')) d = d.slice(2);
  else if (rules.national_prefix && rules.country_code && d.startsWith(rules.national_prefix) && !d.startsWith(rules.country_code)) {
    d = rules.country_code + d.slice(rules.national_prefix.length);
  }
  return d.length >= 9 && d.length <= 15 ? '+' + d : '';
}
function emailOf(value) {
  const e = String(value || '').trim().toLowerCase();
  return /^[^\s@<>()",;]+@[^\s@<>()",;]+\.[a-z]{2,}$/.test(e) ? e : '';
}
const localText = (ms) => new Intl.DateTimeFormat(cfg.locale || 'ru-RU', {
  timeZone: cfg.timezone, day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit',
}).format(new Date(ms));
function localParts(ms) {
  const parts = {};
  for (const p of new Intl.DateTimeFormat('en-GB', { timeZone: cfg.timezone, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', weekday: 'short' }).formatToParts(new Date(ms))) parts[p.type] = p.value;
  return { date: `${parts.year}-${parts.month}-${parts.day}`, hour: Number(parts.hour), minute: Number(parts.minute), weekday: parts.weekday.toLowerCase().slice(0, 3) };
}
const sheetUrl = (path) => `${cfg.sheets_api_base}/spreadsheets/${encodeURIComponent(cfg.spreadsheet_id)}/values/${path}`;
const quoteSheet = (name) => "'" + String(name).replace(/'/g, "''") + "'";
// Deals sheet: one row per deal, contact details included. Dates are local time "YYYY-MM-DD HH:MM" so people can read and edit them.
const DCOLS = ['id', 'created_at', 'updated_at', 'source', 'name', 'phone', 'email', 'company', 'need', 'amount', 'stage', 'owner', 'next_action',
  'next_action_at', 'last_activity_at', 'reminded_at', 'escalated_at', 'lost_reason', 'closed_at', 'repeat', 'history', 'notes'];
const colLetter = (index) => String.fromCharCode(65 + index);
const DLAST = colLetter(DCOLS.length - 1);
const dealsRange = () => `${quoteSheet(cfg.deals_sheet)}!A1:${DLAST}`;
const dealRow = (row) => `${quoteSheet(cfg.deals_sheet)}!A${row}:${DLAST}${row}`;
const dealsReadUrl = () => sheetUrl(encodeURIComponent(dealsRange())) + '?valueRenderOption=UNFORMATTED_VALUE&dateTimeRenderOption=SERIAL_NUMBER';
function dealsTable(values) {
  const all = values || [];
  const header = all.length > 0 && String(all[0][0]).trim().toLowerCase() === 'id';
  return { header, rows: (header ? all.slice(1) : all).map((r, i) => ({ sheetRow: i + (header ? 2 : 1), deal: dealObject(r) })).filter((x) => x.deal.id) };
}
function dealObject(row) {
  const o = {};
  DCOLS.forEach((c, i) => { const v = row[i]; o[c] = v === undefined || v === null ? '' : typeof v === 'number' && /_at$/.test(c) ? v : String(v).trim(); });
  o.stage = o.stage || 'new';
  return o;
}
const putDeal = (sheetRow, deal) => ({ method: 'PUT', url: sheetUrl(encodeURIComponent(dealRow(sheetRow))) + '?valueInputOption=RAW', body: { values: [DCOLS.map((c) => String(deal[c] === undefined ? '' : deal[c]))] } });
const appendDeal = (deal, hasHeader) => ({ method: 'POST', url: sheetUrl(encodeURIComponent(dealsRange()) + ':append') + '?valueInputOption=RAW&insertDataOption=INSERT_ROWS',
  body: { values: [...(hasHeader ? [] : [DCOLS]), DCOLS.map((c) => String(deal[c] === undefined ? '' : deal[c]))] } });
const cellWrite = (sheetRow, col, value) => ({ range: `${quoteSheet(cfg.deals_sheet)}!${colLetter(DCOLS.indexOf(col))}${sheetRow}`, values: [[String(value)]] });
const batchUpdate = (data) => ({ method: 'POST', url: `${cfg.sheets_api_base}/spreadsheets/${encodeURIComponent(cfg.spreadsheet_id)}/values:batchUpdate`, body: { valueInputOption: 'RAW', data } });

function localToMs(y, mo, d, h, mi) {
  const want = Date.UTC(y, mo - 1, d, h, mi);
  let guess = want;
  for (let i = 0; i < 3; i++) {
    const p = localParts(guess);
    guess += want - Date.UTC(Number(p.date.slice(0, 4)), Number(p.date.slice(5, 7)) - 1, Number(p.date.slice(8, 10)), p.hour, p.minute);
  }
  return guess;
}
// A date cell (serial number), "2026-10-28 10:00", "28.10.2026 10:00" or an ISO timestamp — in the Config time zone.
function whenOf(value) {
  if (value === '' || value === null || value === undefined) return null;
  if (typeof value === 'number' || /^\d+(\.\d+)?$/.test(String(value))) {
    const wall = new Date(Math.round((Number(value) - 25569) * 86400000));
    return localToMs(wall.getUTCFullYear(), wall.getUTCMonth() + 1, wall.getUTCDate(), wall.getUTCHours(), wall.getUTCMinutes());
  }
  const s = String(value).trim();
  if (/^\d{4}-\d{2}-\d{2}T.*(Z|[+-]\d{2}:?\d{2})$/.test(s)) return Date.parse(s);
  let m = /^(\d{4})-(\d{1,2})-(\d{1,2})(?:[ T](\d{1,2}):(\d{2}))?/.exec(s);
  if (m) return localToMs(+m[1], +m[2], +m[3], +(m[4] || 9), +(m[5] || 0));
  m = /^(\d{1,2})[./](\d{1,2})[./](\d{4})(?:,?\s+(\d{1,2}):(\d{2}))?/.exec(s);
  if (m) return localToMs(+m[3], +m[2], +m[1], +(m[4] || 9), +(m[5] || 0));
  return NaN;
}
const pad = (n) => String(n).padStart(2, '0');
const stamp = (ms) => { const p = localParts(ms); return `${p.date} ${pad(p.hour)}:${pad(p.minute)}`; };
const toMin = (t) => { const [h, m] = String(t).split(':').map(Number); return h * 60 + (m || 0); };
const dayAt = (ms, hhmm) => { const p = localParts(ms); const t = toMin(hhmm); return localToMs(+p.date.slice(0, 4), +p.date.slice(5, 7), +p.date.slice(8, 10), Math.floor(t / 60), t % 60); };
function inWorkingHours(ms) {
  const p = localParts(ms);
  const day = (cfg.working_hours || {})[p.weekday];
  const m = p.hour * 60 + p.minute;
  return Boolean(day) && m >= toMin(day.open) && m < toMin(day.close);
}
// The same moment if it falls in working hours, otherwise the next opening.
function nextWorking(ms) {
  if (inWorkingHours(ms)) return ms;
  for (let i = 0; i < 8; i++) {
    const probe = ms + i * 24 * 60 * MIN;
    const day = (cfg.working_hours || {})[localParts(probe).weekday];
    if (!day) continue;
    const open = dayAt(probe, day.open);
    if (open > ms) return open;
  }
  return ms;
}
const stageOf = (id) => (cfg.stages || []).find((s) => s.id === id) || { id, label: id };
const isClosed = (deal) => deal.stage === 'won' || deal.stage === 'lost';
const ownerByName = (name) => (cfg.owners || []).find((o) => o.name === name);
const ownerByChat = (chat) => (cfg.owners || []).find((o) => String(o.chat_id) === String(chat));
const amountOf = (v) => { const n = Number(String(v || '').replace(/\s/g, '').replace(/[^\d.,-]/g, '').replace(',', '.')); return Number.isFinite(n) ? n : 0; };
const money = (n) => `${Math.round(n).toLocaleString('ru-RU').replace(/\s/g, ' ')}${cfg.currency ? ' ' + cfg.currency : ''}`;
const addHistory = (deal, ms, who, text) => { deal.history = `${deal.history ? deal.history + '\n' : ''}${stamp(ms)} · ${who}: ${String(text).replace(/\n+/g, ' ').slice(0, 300)}`.slice(-4000); };
function card(deal, title) {
  const at = whenOf(deal.next_action_at);
  const lines = [
    `${title} ${deal.id}`,
    deal.name ? `Имя: ${deal.name}` : '', deal.phone ? `Телефон: ${deal.phone}` : '', deal.email ? `Почта: ${deal.email}` : '', deal.company ? `Компания: ${deal.company}` : '',
    deal.need ? `Запрос: ${deal.need.slice(0, 600)}` : '', deal.amount ? `Сумма: ${deal.amount}` : '', deal.source ? `Источник: ${deal.source}` : '',
    `Этап: ${stageOf(deal.stage).label}${deal.owner ? ' · ' + deal.owner : ''}`,
    deal.next_action ? `Следующий шаг: ${deal.next_action}${at ? ' — ' + stamp(at) : ''}` : '',
  ].filter(Boolean);
  return lines.join('\n') + '\n\nОтветьте на это сообщение: заметка, «сумма: 1500», «напомнить: завтра 15:00 перезвонить», «причина: дорого».\nID: ' + deal.id;
}
const table = dealsTable($input.first().json.values);
const now = nowMs();
const at = stamp(now);
if (!inWorkingHours(now)) return [{ json: { send: false, reason: 'outside_hours' } }];
const items = [];
const data = [];
const DAY = 24 * 60 * MIN;
for (const { sheetRow, deal } of table.rows) {
  if (isClosed(deal)) continue;
  const owner = ownerByName(deal.owner);
  const chat = owner && owner.chat_id ? owner.chat_id : cfg.team_chat_id;
  const next = whenOf(deal.next_action_at);
  const reminded = whenOf(deal.reminded_at) || 0;
  const created = whenOf(deal.created_at) || now;
  const activity = whenOf(deal.last_activity_at) || created;
  // Nobody touched a new deal: the team chat hears about it once.
  if (deal.stage === 'new' && !deal.escalated_at && cfg.team_chat_id && now - created >= (cfg.escalate_after_minutes || 120) * MIN) {
    items.push({ send: true, chat: cfg.team_chat_id, text: `Новая сделка без ответа ${Math.round((now - created) / 60 / MIN * 10) / 10} ч: ${deal.id} ${deal.name || deal.phone || deal.email}. Ответственный: ${deal.owner || 'не назначен'}.`, buttons: false, id: deal.id });
    data.push(cellWrite(sheetRow, 'escalated_at', at));
  }
  if (next && next <= now && reminded < next) {
    items.push({ send: true, chat, text: card(deal, `Напоминание: ${deal.next_action || 'следующий шаг'} ·`), buttons: true, id: deal.id });
    data.push(cellWrite(sheetRow, 'reminded_at', at));
    continue;
  }
  const quietDays = ((cfg.stages || []).find((s) => s.id === deal.stage) || {}).stale_days;
  if (quietDays && (!next || next < now) && now - activity >= quietDays * DAY && now - reminded >= 20 * 60 * MIN) {
    items.push({ send: true, chat, text: card(deal, `Сделка без движения ${Math.floor((now - activity) / DAY)} дн. ·`), buttons: true, id: deal.id });
    data.push(cellWrite(sheetRow, 'reminded_at', at));
  }
}
if (!items.length) return [{ json: { send: false, reason: 'nothing' } }];
items[0].http = batchUpdate(data);
return items.map((json) => ({ json }));
